        [Input("enforceZdrOpenai")]
        public Input<bool>? EnforceZdrOpenai { get; set; }

        /// <summary>
        /// Whether to enforce zero data retention for models that are not from Anthropic, OpenAI, Google, or xAI. Falls back to EnforceZdr when not provided.
        /// </summary>
        [Input("enforceZdrOther")]
        public Input<bool>? EnforceZdrOther { get; set; }

        /// <summary>
        /// Whether to enforce zero data retention for xAI models. Falls back to EnforceZdr when not provided.
        /// </summary>
        [Input("enforceZdrXai")]
        public Input<bool>? EnforceZdrXai { get; set; }

        [Input("ignoredModels")]
        private InputList<string>? _ignoredModels;

        /// <summary>
        /// Array of model identifiers to exclude from routing (slug or CanonicalSlug accepted)
        /// </summary>
        public InputList<string> IgnoredModels
        {
            get => _ignoredModels ?? (_ignoredModels = new InputList<string>());
            set => _ignoredModels = value;
        }

        [Input("ignoredProviders")]
        private InputList<string>? _ignoredProviders;

        /// <summary>
        /// List of provider IDs to exclude from routing
        /// </summary>
        public InputList<string> IgnoredProviders
        {
            get => _ignoredProviders ?? (_ignoredProviders = new InputList<string>());
            set => _ignoredProviders = value;
        }

        /// <summary>
        /// Whether BYOK (bring-your-own-key) inference spend counts toward this guardrail's limit_usd, in addition to OpenRouter credit spend. Defaults to false.
        /// </summary>
        [Input("includeByokInBudgets")]
        public Input<bool>? IncludeByokInBudgets { get; set; }

        /// <summary>
        /// Spending limit in USD. Must be provided together with `ResetInterval`: a request that sets only one of the two is rejected with a 400.
        /// </summary>
        [Input("limitUsd")]
        public Input<double>? LimitUsd { get; set; }

        /// <summary>
        /// Name for the new guardrail
        /// </summary>
        [Input("name")]
        public Input<string>? Name { get; set; }

        /// <summary>
        /// Interval at which the limit resets (daily, weekly, monthly). must be one of ["daily", "weekly", "monthly"]
        /// </summary>
        [Input("resetInterval")]
        public Input<string>? ResetInterval { get; set; }

        /// <summary>
        /// ISO 8601 timestamp of when the guardrail was last updated
        /// </summary>
        [Input("updatedAt")]
        public Input<string>? UpdatedAt { get; set; }

        /// <summary>
        /// The workspace to create the guardrail in. When omitted, an organization management key creates the guardrail in the default workspace (a 400 if that default has been deleted, so pass `WorkspaceId` explicitly) and a workspace-scoped key creates it in its own workspace. A workspace-scoped key gets a 403 for any other workspace. This only places the guardrail in the workspace; the created guardrail enforces nothing for that workspace's traffic until it is assigned to API keys or members. To restrict all traffic in a workspace, update the workspace's default guardrail instead. Requires replacement if changed.
        /// </summary>
        [Input("workspaceId")]
        public Input<string>? WorkspaceId { get; set; }

        public GuardrailState()
        {
        }
        public static new GuardrailState Empty => new GuardrailState();
    }
}
